* { box-sizing: border-box; }

body {
     margin: 0;
     min-height: 100vh;
     padding: 32px 16px;
     font-family: Georgia, "Times New Roman", serif;
     background: linear-gradient(180deg, #7ec8e3, #0a5c8a);
     display: flex;
     justify-content: center;

    align-items: flex-start;
}

.bai-viet {
    width: min(820px, 100%);
    background: rgba(255, 255, 255, 0.95);
    border-radius: 10px;
    padding: 28px;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.25);
    display: flow-root;
}

.bai-viet h1 {
    margin: 0 0 18px;
    text-align: center;
    color: #0b3d5c;
    font-size: 26px;
}

.sapo {
    background: #0b3d5c;
    color: #ffffff;
    font-style: italic;
    padding: 14px 18px;
    border-radius: 6px;
    line-height: 1.7;
    margin: 0 0 18px;
}

.anh-minh-hoa {
    float: right;
    width: 280px;
    margin: 0 0 14px 18px;
    border-radius: 8px;
}

.than-bai {
    margin: 0 0 14px;

      line-height: 1.8;
      text-align: justify;
      color: #1b1b1b;
  }

  .than-bai::first-letter {
      font-size: 3rem;
      font-weight: 700;
      color: #0b3d5c;
      float: left;
      line-height: 0.85;
      padding: 0.1rem 0.4rem 0 0;
  }

  @media (max-width: 600px) {
      .anh-minh-hoa {
          float: none;
          width: 100%;
          margin: 0 0 14px 0;
      }
  }
